import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { Product } from "../../types/Product";
import { BreadCrumbs } from "../../components/BreadCrumbs/BreadCrumbs";
import { NotFound } from "../../components/NotFound/NotFound";
import { ModelsCounter } from "../../components/ModelsCounter/ModelsCounter";
import { ProductList } from "../../components/ProductList/ProductList";
import { Loader } from "../../components/Loader";
import { getProductByCategory } from "../../api/productsApi";
import { CATEGORY_NAME_MAP } from "../../types/Pathnames";

export const CategoryPage: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [productCount, setProductCount] = useState(products?.length);
  const { pathname } = useLocation();

  const rawSlug = pathname.slice(1);
  const slug = decodeURIComponent(rawSlug);
  const categoryName = CATEGORY_NAME_MAP[slug] || slug;

  async function loadProducts() {
    setIsLoading(true);

    try {
      const productsFromServer = await getProductByCategory(categoryName);

      setProducts(productsFromServer);
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    loadProducts();
  }, [categoryName]);

  const handleVisibleProductsNumber = (number: number) => {
    setProductCount(number);
  };

  return (
    <>
      {isLoading && <Loader />}

      {!isLoading && (
        <div className={`page__${categoryName}`}>
          <BreadCrumbs />
          <h1 className="page__title">{categoryName}</h1>
          <ModelsCounter number={productCount} />

          {!products.length ? (
            <NotFound
              title={`Sorry, we are temporarily not selling ${categoryName}. 
                Please come back in a month.`}
            />
          ) : (
            <ProductList
              products={products}
              handleVisibleProductsNumber={handleVisibleProductsNumber}
              isSortDropdownShown
              isPaginationShown
            />
          )}
        </div>
      )}
    </>
  );
};
